// trace:TASK-3325 | ai:codex
use std::{fs, path::Path};

use aida_core::ai::responses;
use aida_core::models;
use aida_core::team;
use aida_core::typescript::declaration;

fn generate_types_content() -> String {
    const HEADER: &str = "// This file was generated by `aida-generate-types`.\n
// Do not edit this file manually.\n
// It is used to keep Rust and TypeScript types in sync.";

    // Mirrors the server-private `QueueEntryResponse` (aida-server/src/rest.rs,
    // serde rename_all = "camelCase"). See the note at the emit site.
    // trace:STORY-522 | ai:claude
    const QUEUE_ENTRY_DECL: &str = "\n\nexport type QueueEntry = {
    requirementId: string;
    specId: string | null;
    title: string;
    status: string;
    priority: string;
    reqType: string;
    position: number;
    addedBy: string;
    note: string | null;
    addedAt: string;
};";

    let decls: Vec<String> = vec![
        // Raw verify blocks retain invalid JSON-compatible data for reporting.
        // trace:STORY-1673 | ai:codex
        declaration::<serde_json::Value>(),
        // Models from aida_core::models
        declaration::<models::RequirementStatus>(),
        // STORY-332: punt / NeedsAttention types
        declaration::<models::PuntCategory>(),
        declaration::<models::AttentionReason>(),
        // EPIC-28: orchestrator phase-failure reason (referenced by
        // Requirement.failure_reason — must be exported alongside it)
        declaration::<models::FailureReason>(),
        // STORY-522: async decision-inbox types
        declaration::<models::DecisionChoice>(),
        // DecisionRequest's retained-work binding must be exported too.
        // trace:STORY-2661 | ai:codex
        declaration::<models::ParkBinding>(),
        declaration::<models::DecisionRequest>(),
        declaration::<models::RequirementPriority>(),
        declaration::<models::RequirementType>(),
        declaration::<models::MetaSubtype>(),
        declaration::<models::RelationshipType>(),
        declaration::<models::CustomFieldType>(),
        declaration::<models::CustomFieldDefinition>(),
        declaration::<models::CustomTypeDefinition>(),
        declaration::<models::Cardinality>(),
        declaration::<models::RelationshipDefinition>(),
        declaration::<models::IdFormat>(),
        declaration::<models::NumberingStrategy>(),
        declaration::<models::RequirementTypeDefinition>(),
        declaration::<models::FeatureDefinition>(),
        declaration::<models::IdConfiguration>(),
        declaration::<models::RelationshipValidation>(),
        declaration::<models::Relationship>(),
        declaration::<models::FieldChange>(),
        declaration::<models::HistoryEntry>(),
        // STORY-542: Requirement.interface_changes references InterfaceChanges,
        // so its definition must be emitted too (else the web dashboard
        // type-check fails with "Cannot find name 'InterfaceChanges'"). BUG-516.
        // trace:BUG-516 | ai:claude
        declaration::<models::InterfaceChanges>(),
        declaration::<models::ReactionDefinition>(),
        declaration::<models::CommentReaction>(),
        declaration::<models::UrlOpenMode>(),
        declaration::<models::UrlLink>(),
        declaration::<models::Attachment>(),
        declaration::<models::ArtifactType>(),
        declaration::<models::TraceLink>(),
        declaration::<models::GitLabLinkType>(),
        declaration::<models::GitLabIssueLink>(),
        declaration::<models::LinkOrigin>(),
        declaration::<models::SyncStatus>(),
        declaration::<models::GitLabSyncState>(),
        declaration::<models::ConfidenceLevel>(),
        declaration::<models::ImplementationInfo>(),
        declaration::<models::Comment>(),
        declaration::<models::User>(),
        declaration::<models::Team>(),
        // Requirement references these nested types, so they must be emitted
        // alongside it or the web type-check fails with "Cannot find name"
        // (same class as the BUG-516 InterfaceChanges fix).
        // STORY-639 assignment audit trail / STORY-582 processing records /
        // STORY-631 cached intent. trace:STORY-648 | ai:claude
        declaration::<models::ProcessingRecord>(),
        declaration::<models::SpecIntent>(),
        // Regenerating Requirement must emit every nested model it names
        // (optional fields, verify data, hypothesis locks).
        // trace:STORY-1673 | ai:codex
        // trace:STORY-1675 | ai:codex
        declaration::<models::ExecutionMode>(),
        declaration::<models::Origin>(),
        declaration::<models::FilingProvenance>(),
        declaration::<models::HypothesisLock>(),
        declaration::<models::Requirement>(),
        // BUG-571: lightweight web-DTO projection of Requirement (list/board/
        // dashboard fetch this via GET /api/v2/requirements?view=summary so the
        // client stops downloading the ~6.5MB full graph on every view).
        declaration::<models::RequirementSummaryDto>(),
        declaration::<models::RequirementSnapshot>(),
        declaration::<models::Baseline>(),
        declaration::<models::BaselineComparison>(),
        declaration::<models::BaselineRequirementDiff>(),
        declaration::<models::AiActionPromptConfig>(),
        declaration::<models::AiTypePromptConfig>(),
        declaration::<models::AiPromptConfig>(),
        declaration::<models::RequirementsStore>(),
        // Models from aida_core::ai::responses
        declaration::<responses::IssueReport>(),
        declaration::<responses::SuggestedImprovement>(),
        declaration::<responses::EvaluationResponse>(),
        declaration::<responses::StoredAiEvaluation>(),
        declaration::<responses::DuplicateResult>(),
        declaration::<responses::DuplicatesResponse>(),
        declaration::<responses::RelationshipSuggestion>(),
        declaration::<responses::SuggestRelationshipsResponse>(),
        declaration::<responses::ImproveDescriptionResponse>(),
        declaration::<responses::GeneratedChild>(),
        declaration::<responses::GenerateChildrenResponse>(),
        // STORY-648: team dashboard DTOs (feed /api/v2/team + /coordination)
        declaration::<team::TeamMemberDto>(),
        declaration::<team::CoordinationClaimDto>(),
    ];

    let mut body = decls
        .into_iter()
        .map(|d| {
            let trimmed = d.trim_start();
            if trimmed.starts_with("export") {
                d
            } else {
                format!("export {trimmed}")
            }
        })
        .collect::<Vec<_>>()
        .join("\n\n");

    // The web dashboard's queue views (`@shared/types` -> QueueEntry) consume
    // the REST queue list/add response, whose Rust source of truth is the
    // server-private `QueueEntryResponse` struct in `aida-server/src/rest.rs`
    // (serde rename_all = "camelCase"). That struct cannot derive `TS` here
    // without pulling an aida-server dependency into this binary, so the type
    // is emitted verbatim. Keep this declaration field-for-field in sync with
    // `QueueEntryResponse`. trace:STORY-522 | ai:claude
    body.push_str(QUEUE_ENTRY_DECL);

    // Keep generated declarations free of trailing spaces from ts-rs output.
    // trace:STORY-1674 | ai:codex
    format!("{HEADER}\n\n{body}")
        .lines()
        .map(str::trim_end)
        .collect::<Vec<_>>()
        .join("\n")
}

fn main() {
    let types_path = Path::new("shared/types.ts");

    // Create the directory if it doesn't exist
    if let Some(parent) = types_path.parent() {
        fs::create_dir_all(parent).expect("Unable to create shared directory");
    }

    let generated_content = generate_types_content();

    fs::write(types_path, generated_content).expect("Unable to write types.ts");
    println!("✅ TypeScript types generated in shared/types.ts");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_types_match_checked_in_contract() {
        assert_eq!(
            generate_types_content(),
            include_str!("../../shared/types.ts")
        );
    }
}
